CREATE TABLE nursing_entry(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), record_id VARCHAR(36) NOT NULL UNIQUE REFERENCES clinical_record(id), entry_type VARCHAR(40) NOT NULL, prescription_id VARCHAR(36) REFERENCES clinical_record(id), dose VARCHAR(120), route VARCHAR(80), pain_score INTEGER CHECK(pain_score>=0 AND pain_score<=10), intake_ml INTEGER CHECK(intake_ml>=0), output_ml INTEGER CHECK(output_ml>=0), room VARCHAR(100), task_id VARCHAR(36) REFERENCES care_task(id));
CREATE TABLE clinical_attestation(id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL REFERENCES healthcare_organization(id), record_id VARCHAR(36) NOT NULL REFERENCES clinical_record(id), signer_id VARCHAR(36) NOT NULL REFERENCES app_user(id), content_hash VARCHAR(64) NOT NULL, signed_at VARCHAR(40) NOT NULL, purpose VARCHAR(80) NOT NULL);
ALTER TABLE care_message ADD COLUMN priority VARCHAR(20) NOT NULL DEFAULT 'routine';
